Follow this complete example.
```swift
protocol NamedCard {
    var name: String { get }
    func caption() -> String
}
extension NamedCard {
    func caption() -> String {
        return "Card: " + name
    }
}
struct PlainCard: NamedCard {
    let name: String
}
struct SpecialCard: NamedCard {
    let name: String
    func caption() -> String {
        return "Special: " + name
    }
}
func show(_ card: any NamedCard) -> String {
    return card.caption()
}
print(show(PlainCard(name: "oak")))
print(show(SpecialCard(name: "ash")))
```
Output:
```text
Card: oak
Special: ash
```

